// F09 / RM-UI-DETAIL r2: minimum standalone overview. Explicit advanced demos remain available.
const overviewStates=new Map();
function overviewState(i){if(!overviewStates.has(i.key))overviewStates.set(i.key,{read:'ok',conversation:true,room:'unknown'});return overviewStates.get(i.key)}
const overviewButton=(label,action)=>`<button type="button" data-overview="${action}">${label}</button>`;
const previousIssuePage=issuePage;
issuePage=function(i){
 if(!i||state.repo||state.view!=='overview')return previousIssuePage(i);
 const s=overviewState(i),c=items.find(x=>x.key===i.conversationKey);
 const back=`<div class="rm-source">${state.roomNavOrigin?btn('← 返回会话','room-index-return'):btn('← Issue 列表','issues')}<span>Issue 概览</span></div>`;
 const demo=`<details class="min-overview-tools"><summary>详情演示场景 · 待评审</summary><div>${overviewButton('正常读取','normal')}${overviewButton('读取失败','error')}${overviewButton('关联会话不可读','restricted')}${overviewButton('有依据正在准备','preparing')}${overviewButton('主房间暂不可用','unavailable')}</div><small>仅页面样例，无真实查询、授权或运行事件。</small></details>`;
 if(s.read==='error')return back+`<div class="rm-room-body"><div class="rm-details"><h1>暂时无法读取 Issue</h1><p>未取得当前记录，请重新读取后查看。</p>${overviewButton('重新读取（模拟）','normal')}${demo}</div></div>`;
 const observation=s.room==='preparing'?['正在准备主房间','已取得本次准备中的样例观察；尚不能进入实时房间。']:s.room==='unavailable'?['主房间暂不可用','当前不可进入实时房间，工作记录仍保留。']:['运行状态待确认','工作记录已保存；尚未取得主房间就绪依据。'];
 return back+`<header class="rm-room-heading"><div><h1>#${i.number} ${esc(i.title)}</h1><div class="rm-room-meta">${badge('记录已保存','green')}<span>${esc(project().name)}</span></div></div></header><div class="rm-room-body"><div class="rm-details min-overview"><section class="min-state"><div><strong>${observation[0]}</strong><p>${observation[1]}</p></div>${overviewButton('重新读取状态','refresh')}</section><section><h2>工作目标</h2><p class="min-goal">${esc(i.body)}</p></section><section><h2>涉及仓库 <small>· ${scope(i).length}</small></h2><div class="rm-detail-repos">${scope(i).map(r=>'<span>'+esc(r)+'</span>').join('')}</div><p class="rm-note">本 Issue 的明确范围，项目后续加仓不会自动加入。</p></section><section class="min-conversation"><div><h2>关联会话</h2><p>${s.conversation&&c?esc(c.title):'关联会话当前不可读取'}</p><small>${s.conversation&&c?'可查看已保存的讨论记录；与主房间是否就绪分开判断。':'本 Issue 仍可独立查看，隐藏会话名称与进入入口。'}</small></div>${s.conversation&&c?btn('查看关联会话 →','view-source-conversation',i.key):''}</section><div class="min-meta"><span>主 ChangeSet · CS-${i.number}</span><span>状态观察 · ${s.room==='unknown'?'尚未取得有效时间':'本次预置样例'}</span></div>${s.refreshed?'<p class="rm-note" role="status">已重新读取样例；未取得新的就绪依据，状态未改变。</p>':''}${demo}</div></div>`;
};
const overviewRender=render;
render=function(){overviewRender();if(state.panel==='issue'&&state.view==='overview'&&!state.repo){root.querySelector('.rm-top-right>span')?.remove();root.querySelector('.rm-demo-ready')?.remove();joined.report('workspace','issue/'+state.issueKey+'/overview','F09 · 最小详情概览待评审 · 仅原型状态')}};
mount.addEventListener('click',e=>{const a=e.target.closest('[data-overview]')?.dataset.overview;if(!a)return;e.preventDefault();e.stopImmediatePropagation();const i=activeIssue();if(!i)return;const s=overviewState(i);if(a==='normal')Object.assign(s,{read:'ok',conversation:true,room:'unknown',refreshed:false});if(a==='error')s.read='error';if(a==='restricted')s.conversation=false;if(a==='preparing')s.room='preparing';if(a==='unavailable')s.room='unavailable';if(a==='refresh')s.refreshed=true;render()},true);
const overviewNavigate=window.joinedAPI.navigate;
window.joinedAPI.navigate=function(route){if(route==='issue-overview'){const i=issues.find(x=>x.key===detailIssue.key)||issues[0];overviewNavigate('issue/'+i.key+'/overview');return}overviewNavigate(route)};
const overviewStyle=document.createElement('style');overviewStyle.textContent='#repomesh-rooms-prototype .min-overview{padding-top:18px}#repomesh-rooms-prototype .min-overview>section{margin-bottom:24px}#repomesh-rooms-prototype .min-state{display:flex;justify-content:space-between;gap:14px;align-items:center;padding:15px;border:1px solid #464139;background:#24211d;border-radius:8px}#repomesh-rooms-prototype .min-state strong{font-size:13px;color:#d4c4a8}#repomesh-rooms-prototype .min-state p{margin:4px 0 0;font-size:12px;color:#aaa}#repomesh-rooms-prototype .min-state button{white-space:nowrap;font-size:12px;border:1px solid #4b4840}#repomesh-rooms-prototype .min-goal{white-space:pre-wrap;line-height:1.8}#repomesh-rooms-prototype .min-conversation{display:flex;align-items:center;justify-content:space-between;gap:16px;border-top:1px solid #333;padding-top:20px}#repomesh-rooms-prototype .min-conversation p{margin:8px 0;font-size:14px}#repomesh-rooms-prototype .min-conversation small{font-size:11px;color:#999}#repomesh-rooms-prototype .min-conversation button{white-space:nowrap}#repomesh-rooms-prototype .min-meta{border-top:1px solid #303030;padding-top:14px;display:flex;gap:18px;flex-wrap:wrap;color:#858585;font-size:11px}#repomesh-rooms-prototype .min-overview-tools{margin:22px 0;color:#999;font-size:11px}#repomesh-rooms-prototype .min-overview-tools summary{cursor:pointer}#repomesh-rooms-prototype .min-overview-tools>div{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}#repomesh-rooms-prototype .min-overview-tools button{font-size:11px;border:1px solid #3c3c3c;padding:5px 8px}@media(max-width:600px){#repomesh-rooms-prototype .min-state,#repomesh-rooms-prototype .min-conversation{align-items:flex-start;flex-direction:column}}';document.head.append(overviewStyle);
